// Verifies Benchmark's signature, then turns approval events into one sheet row each.
// n8n needs NODE_FUNCTION_ALLOW_BUILTIN=crypto for require('crypto').
const crypto = require('crypto');
const SECRET = 'PASTE_WEBHOOK_SECRET_FROM_RENDER';
const TOLERANCE_SECONDS = 300;

const rows = [];
for (const item of $input.all()) {
  const headers = item.json.headers || {};
  const body = JSON.stringify(item.json.body); // Benchmark sends canonical JSON, so this rebuilds the exact bytes
  const ts = headers['x-benchmark-timestamp'];
  const expected = 'sha256=' + crypto.createHmac('sha256', SECRET).update(`${ts}.${body}`).digest('hex');
  const given = headers['x-benchmark-signature'] || '';
  const fresh = Math.abs(Date.now() / 1000 - Number(ts)) <= TOLERANCE_SECONDS;
  const same = given.length === expected.length && crypto.timingSafeEqual(Buffer.from(given), Buffer.from(expected));
  if (!fresh || !same) throw new Error('Rejected: bad or stale Benchmark signature');

  const event = item.json.body;
  if (event.event !== 'approval.recorded') continue;
  const d = event.data;
  rows.push({ json: {
    received: event.at, day: d.day, item: d.item.id, label: d.item.label,
    action: d.act, approvedBy: d.by, via: d.via, detail: d.detail, delivery: event.id,
  } });
}
return rows;
